dy = ( GetBlur1(uv+vec2( 0.0 , 1.0 )*d)-GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy );
vec3 base = GetPixel(uv);
vec3 emboss = (-dx + dy + 1.0)*1.4;
float grad_x = length(vec2(dx.x,dy.x));
float grad_y = length(vec2(dx.y,dy.y));
ret = mix( vec3(0.6,0.5,0.4)*base.x*emboss.x,
vec3( 4.0 , 2.0 , 1.0 )*grad_x,
grad_x * 2.0
);
ret = mix(ret, vec3(0.3, 0.0 , 0.0), julia * 4.0);
ret = mix(ret, vec3( 0.0 , 0.0 ,1.4), grad_y*1.4);
